cd /app && sqlite3 subset.sqlite <<'EOF'
ATTACH '/app/oewn.sqlite' AS full;
CREATE TABLE words AS
  SELECT full.words.* FROM full.words WHERE wordid IN (
    36,252,354,413,423,427,429,436,440,452,389,4563,41575,75842,98871,144778
  ) OR wordid IN (SELECT value FROM (SELECT '' AS value));
EOF
echo "---"

cd /app && rm -f subset.sqlite && sqlite3 subset.sqlite <<'EOF'
ATTACH '/app/oewn.sqlite' AS full;
CREATE TABLE words AS
  SELECT "words".* FROM full."words"
  WHERE "wordid" IN (
    36,252,354,413,423,427,429,436,440,452,389,4563,41575,75842,98871,144778
  );
EOF
# add the 120 random ones
IDLIST=$(paste -sd, words.txt)
sqlite3 subset.sqlite "
ATTACH '/app/oewn.sqlite' AS full;
INSERT INTO words SELECT \"words\".* FROM full.\"words\" WHERE \"wordid\" IN ($IDLIST);
CREATE TABLE senses AS SELECT \"senses\".* FROM full.\"senses\" WHERE \"wordid\" IN (SELECT wordid FROM words);
CREATE TABLE synsets AS SELECT \"synsets\".* FROM full.\"synsets\" WHERE \"synsetid\" IN (SELECT DISTINCT synsetid FROM senses);
SELECT (SELECT COUNT(*) FROM words), (SELECT COUNT(*) FROM senses), (SELECT COUNT(*) FROM synsets);
"

cd /app && sqlite3 oewn.sqlite "
SELECT 'raw:', synsetid, COUNT(*) FROM senses WHERE wordid=41575 GROUP BY synsetid ORDER BY 3 DESC, 2 ASC LIMIT 5;
SELECT 'joined:', s.synsetid, COUNT(*) FROM senses s JOIN words w ON w.wordid=s.wordid JOIN synsets syn ON syn.synsetid=s.synsetid WHERE s.wordid=41575 GROUP BY s.wordid, s.synsetid, w.word, syn.domainid, syn.posid ORDER BY 3 DESC LIMIT 5;
SELECT 'senses rows:', senseid, synsetid, luid, lexid FROM senses WHERE wordid=41575 AND synsetid=81973;
"

cd /app && sqlite3 subset.sqlite "
SELECT 'dup senseid:', COUNT(*) FROM (SELECT senseid FROM senses GROUP BY senseid HAVING COUNT(*) > 1);
SELECT 'dup words:', COUNT(*) FROM (SELECT wordid FROM words GROUP BY wordid HAVING COUNT(*) > 1);
SELECT 'dup synset:', COUNT(*) FROM (SELECT synsetid FROM synsets GROUP BY synsetid HAVING COUNT(*) > 1);
SELECT 'per-synset 41575:', s.synsetid, COUNT(*) FROM senses s JOIN words w ON w.wordid=s.wordid JOIN synsets syn ON syn.synsetid=s.synsetid WHERE s.wordid=41575 GROUP BY s.wordid, s.synsetid, w.word, syn.domainid, syn.posid ORDER BY 3 DESC LIMIT 3;
"

cd /app && rm -f subset.sqlite && IDLIST=$(paste -sd, words.txt) && sqlite3 subset.sqlite "
ATTACH '/app/oewn.sqlite' AS full;
CREATE TABLE words AS SELECT \"words\".* FROM full.\"words\" WHERE \"wordid\" IN ($IDLIST);
CREATE TABLE senses AS SELECT \"senses\".* FROM full.\"senses\" WHERE \"wordid\" IN (SELECT wordid FROM words);
CREATE TABLE synsets AS SELECT \"synsets\".* FROM full.\"synsets\" WHERE \"synsetid\" IN (SELECT DISTINCT synsetid FROM senses);
SELECT (SELECT COUNT(*) FROM words), (SELECT COUNT(*) FROM senses), (SELECT COUNT(*) FROM synsets);
SELECT 'dup words:', COUNT(*) FROM (SELECT wordid FROM words GROUP BY wordid HAVING COUNT(*) > 1);
" && sqlite3 -header -csv subset.sqlite < my-sql-query.sql > sub_orig.csv && sqlite3 -header -csv subset.sqlite < sol.sql > sub_sol.csv && diff sub_orig.csv sub_sol.csv && echo "SUBSET: IDENTICAL"

cd /app && tail -n +2 sol_out.csv | cut -d, -f1 > top500.txt && sqlite3 oewn.sqlite "
WITH stats AS (
  SELECT w.wordid,
         COUNT(DISTINCT s.synsetid) AS total_synsets,
         COUNT(*) AS total_senses,
         COUNT(DISTINCT syn.domainid) AS distinct_domains
  FROM words w
  JOIN senses s ON w.wordid = s.wordid
  JOIN synsets syn ON s.synsetid = syn.synsetid
  GROUP BY w.wordid, w.word
  HAVING total_synsets >= 2 AND distinct_domains >= 2 AND total_senses >= 2
)
SELECT wordid FROM stats ORDER BY total_senses DESC, total_synsets DESC, distinct_domains DESC, wordid ASC LIMIT 20 OFFSET 500;
" > below500.txt && cat top500.txt below500.txt | sort -un > subset2_words.txt && wc -l subset2_words.txt && IDLIST=$(paste -sd, subset2_words.txt) && rm -f subset2.sqlite && sqlite3 subset2.sqlite "
ATTACH '/app/oewn.sqlite' AS full;
CREATE TABLE words AS SELECT \"words\".* FROM full.\"words\" WHERE \"wordid\" IN ($IDLIST);
CREATE TABLE senses AS SELECT \"senses\".* FROM full.\"senses\" WHERE \"wordid\" IN (SELECT wordid FROM words);
CREATE TABLE synsets AS SELECT \"synsets\".* FROM full.\"synsets\" WHERE \"synsetid\" IN (SELECT DISTINCT synsetid FROM senses);
SELECT (SELECT COUNT(*) FROM words), (SELECT COUNT(*) FROM senses);
"
